CREATE OR REPLACE FUNCTION "restore_control".assert_pristine_platform_installation() RETURNS void LANGUAGE plpgsql AS $$
DECLARE expected text[] := ARRAY['admin_audit','admin_audit_outbox','admin_command_operations','admin_login_limits','admin_reauth_grants','admin_sessions','admin_users','analytics_daily_summaries','app_schema_migrations','battle_results','deletion_audit','deletion_ledger_outbox','deletion_operations','deletion_preview_designs','deletion_preview_identities','deletion_preview_matches','deletion_previews','design_event_snapshots','design_layers','designs','device_activity_days','identities','identity_links','identity_sessions','match_participant_snapshots','match_persistence_jobs','matches','platform_settings','room_event_snapshots','room_participants','room_projection_jobs','rooms','rounds','webclip_token_nonces'];actual text[];name text;rows bigint;restore_tables text[];restore_sequences text[];restore_functions text[];restore_triggers text[];
BEGIN SELECT array_agg(tablename ORDER BY tablename) INTO actual FROM pg_tables WHERE schemaname='public';IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'durable public schema drift';END IF;
SELECT array_agg(c.relname ORDER BY c.relname) FILTER(WHERE c.relkind IN('r','p')),array_agg(c.relname ORDER BY c.relname) FILTER(WHERE c.relkind='S') INTO restore_tables,restore_sequences FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='restore_control';SELECT array_agg(p.proname ORDER BY p.proname) INTO restore_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='restore_control';SELECT array_agg(t.tgname ORDER BY t.tgname) INTO restore_triggers FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='restore_control' AND NOT t.tgisinternal;
IF restore_tables IS DISTINCT FROM ARRAY['deployment_environment','finalize_outbox','platform_installation','promotion_audit','promotion_outbox'] OR restore_sequences IS DISTINCT FROM ARRAY['promotion_audit_id_seq'] OR restore_functions IS DISTINCT FROM ARRAY['assert_pristine_platform_installation','deletion_audit_sha256','steam_top_protect_deployment_environment'] OR restore_triggers IS DISTINCT FROM ARRAY['deployment_environment_is_protected','deployment_environment_truncate_is_protected'] THEN RAISE EXCEPTION 'restore authority schema drift';END IF;
IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='restore_control' AND (c.relkind NOT IN('r','p','S','i') OR (c.relkind='i' AND NOT EXISTS(SELECT 1 FROM pg_constraint k WHERE k.conindid=c.oid)) OR c.relacl IS NOT NULL)) OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='restore_control' AND p.proacl IS NOT NULL) OR EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='restore_control') THEN RAISE EXCEPTION 'restore authority grants or object drift';END IF;
FOREACH name IN ARRAY expected LOOP EXECUTE format('LOCK TABLE public.%I IN SHARE MODE',name);IF name='platform_settings' THEN IF NOT EXISTS(SELECT 1 FROM public.platform_settings WHERE singleton AND NOT paused) OR (SELECT count(*) FROM public.platform_settings)<>1 THEN RAISE EXCEPTION 'platform settings baseline invalid';END IF;CONTINUE;ELSIF name='app_schema_migrations' THEN IF (SELECT array_agg(id::text ORDER BY id) FROM public.app_schema_migrations) IS DISTINCT FROM ARRAY['0000_steam_top_pre_first_deploy','0001_cutover_state_machine','0002_platform_installation','0003_postgresql_catalog_array_compatibility'] OR (SELECT array_agg(sha256::text ORDER BY id) FROM public.app_schema_migrations) IS DISTINCT FROM ARRAY['51757c37f19429c162cbd2de8f04682e5e8dad0a78723fb142332e5f11d7721f','ca26cdef9195ae550a0fd4eb4db66fe02c2915e646a71e51182b4b4cf8a40571','55a06f26947827ec40a29068fb17cd91a02b2085acaca15a1b2bb95f63c5aefb',current_setting('steam_top.expected_platform_migration_sha',false)] THEN RAISE EXCEPTION 'migration ledger baseline invalid';END IF;CONTINUE;END IF;EXECUTE format('SELECT count(*) FROM public.%I',name) INTO rows;IF rows<>0 THEN RAISE EXCEPTION 'durable table % is not pristine',name;END IF;END LOOP;
LOCK TABLE restore_control.deployment_environment,restore_control.finalize_outbox,restore_control.platform_installation,restore_control.promotion_outbox,restore_control.promotion_audit IN SHARE MODE;IF (SELECT count(*) FROM restore_control.finalize_outbox)<>0 OR (SELECT count(*) FROM restore_control.promotion_outbox)<>0 OR (SELECT count(*) FROM restore_control.promotion_audit)<>0 THEN RAISE EXCEPTION 'restore control data is not pristine';END IF;IF NOT EXISTS(SELECT 1 FROM restore_control.deployment_environment WHERE singleton AND environment='production' AND NOT restore_allowed) OR (SELECT count(*) FROM restore_control.deployment_environment)<>1 THEN RAISE EXCEPTION 'deployment marker baseline invalid';END IF;END$$;
